    steps: [
      { title: "운영 형태 확인", where: "관할 시·군·구청 건축·위생 담당 부서", detail: "일반인에게 공부할 수 있는 방과 숙식을 함께 내주는 고시원은 건축법상 다중생활시설이고 다중이용업소 소방 기준을 따라요. 고시원은 방마다 취사시설이나 욕조를 둘 수 없어요(샤워부스는 가능). 방마다 취사시설을 두고 하루 단위로 손님을 받으면 숙박업 신고 대상이 될 수 있어요. 주택에서 장기 계약으로 숙식을 주는 하숙이 숙박업 신고 대상인지, 고시원에 따로 받는 영업 신고가 있는지는 관할 구청에 확인해요." },
      { title: "계약 전에 건축물 용도 확인", where: "정부24 건축물대장 · 시·군·구청 건축 부서", detail: "고시원은 다중생활시설 용도여야 해요. 같은 건물에서 이 용도로 쓰는 면적이 작으면 제2종 근린생활시설, 크면 숙박시설로 분류돼요. 방은 지하층에 둘 수 없고, 방 최소 면적과 창문 기준을 건축조례로 정한 지자체가 있으니 계약 전에 구청 건축 부서에 확인해요." },
      { title: "공사 전에 소방서에 안전시설 신고", where: "관할 소방서", detail: "고시원업은 다중이용업소예요. 인테리어 공사 전에 설계도서를 붙여 안전시설 설치 신고를 하고, 숙박을 제공하는 영업장이라 간이스프링클러 설치 대상인지 함께 확인해요. 공사를 마치면 완공 신고를 하고 안전시설등 완비증명서를 받아요. 완공 신고 전까지 소방안전교육을 받아요." },
      { title: "화재배상책임보험 가입", where: "보험사", detail: "다중이용업을 하려는 사람은 화재로 다른 사람이 다치거나 재산 피해를 입으면 과실이 없어도 보상하는 화재배상책임보험에 들어야 해요. 문을 열기 전에 가입하고 증서를 보관해요." },
      { title: "사업자등록과 온라인에 알리기", where: "관할 세무서 또는 홈택스 · 오늘창업 홈페이지 · 방 구하기 플랫폼", detail: "사업자등록을 해요. 고시원에 필요한 첨부 서류는 세무서에 미리 물어봐요. 방 사진, 입실료와 포함 항목(식사·세탁), 환불 기준, 이용 규칙을 한곳에 정리해 올려요." },
    ],
    pitfalls: ["방에 개인 취사시설을 넣으면 다중생활시설 기준을 벗어나요. 공용 주방을 따로 두세요.", "방을 늘리거나 내부 통로를 바꾸는 공사도 소방서에 미리 신고해야 해요. 신고 없이 칸막이를 바꾸면 완비증명서 내용과 달라져요.", "다중이용업주는 일정 주기마다 소방안전교육을 다시 받아야 하고, 영업장을 관리하는 직원도 교육 대상이 될 수 있어요."],
    links: [{"title": "국가법령정보센터 · 건축법 시행령 별표1(용도별 건축물의 종류)", "url": "https://www.law.go.kr/법령/건축법시행령"}, {"title": "국가법령정보센터 · 다중생활시설 건축기준(국토교통부 고시)", "url": "https://www.law.go.kr/행정규칙/다중생활시설건축기준"}, {"title": "국가법령정보센터 · 다중이용업소의 안전관리에 관한 특별법(제8조·제9조·제13조의2)", "url": "https://www.law.go.kr/법령/다중이용업소의안전관리에관한특별법"}],
